style.css:
@-moz-document domain("youtube.com") {
* {
    background-color: #cd0000 !important;
    color: #D3AF37 !important;
    border-color: #D3AF37 !important;
  }
  html, body, ytd-app {
    background-color: #cd0000 !important;
    color: #D3AF37 !important;
  }
  #masthead-container, ytd-masthead, #search-form, ytd-searchbox {
    background-color: #8d0000 !important;
    border: none !important;
  }
  ytd-searchbox input#search {
    background-color: #6f0000 !important;
    color: #D3AF37 !important;
    border: none !important;
  }
  ytd-searchbox input#search:focus {
    outline: none !important;
    box-shadow: none !important;
  }
  ytd-guide-section-renderer, ytd-guide-renderer, ytd-mini-guide-renderer, #guide, ytd-mini-guide-entry-renderer {
    background-color: #8d0000 !important;
  }
  ytd-browse, ytd-section-list-renderer, ytd-two-column-browse-results-renderer, ytd-rich-grid-renderer, ytd-rich-section-renderer, ytd-rich-item-renderer {
    background-color: #cd0000 !important;
  }
  ytd-feed-filter-chip-bar-renderer, ytd-feed-filter-chip-bar-renderer #chips-wrapper, yt-chip-cloud-chip-renderer, yt-chip-cloud-chip-renderer[selected] {
    background-color: #6f0000 !important;
    color: #D3AF37 !important;
    border-color: #D3AF37 !important;
  }
  ytd-feed-filter-chip-bar-renderer::before, ytd-feed-filter-chip-bar-renderer::after {
    display: none !important;
    background: none !important;
  }
  #video-title, ytd-video-renderer #video-title, ytd-grid-video-renderer #video-title, ytd-rich-grid-media #video-title-link, ytd-compact-video-renderer #video-title, ytd-reel-item-renderer #video-title, a[href*="/game/"], ytd-channel-name, a.yt-simple-endpoint.style-scope.yt-formatted-string, ytd-video-meta-block, #metadata-line span {
    color: #D3AF37 !important;
  }
  #comments, ytd-comments, ytd-comment-thread-renderer, ytd-comment-renderer, #placeholder-area {
    background-color: #cd0000 !important;
    color: #D3AF37 !important;
  }
  #player-container, #movie_player, ytd-player {
    background-color: #8d0000 !important;
  }
  tp-yt-paper-dialog, ytd-popup-container, ytd-menu-popup-renderer, tp-yt-iron-dropdown, ytd-tooltip-renderer {
    background-color: #8d0000 !important;
    color: #D3AF37 !important;
  }
  #logo-icon, #logo-icon > svg {
    display: none !important;
  }
  ytd-topbar-logo-renderer {
    position: relative !important;
  }
  ytd-topbar-logo-renderer a#logo {
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    width: 120px !important;
    height: 40px !important;
    background-color: #8d0000 !important;
    border-radius: 4px !important;
  }
  ytd-topbar-logo-renderer a#logo::after {
    content: "";
    background-image: url("https://upload.wikimedia.org/wikipedia/commons/3/31/Soviet_Hammer_and_Sickle_%281924%29.svg");
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    width: 100%;
    height: 100%;
    display: block;
  }
  tp-yt-paper-button, tp-yt-paper-icon-button, ytd-subscribe-button-renderer, ytd-toggle-button-renderer, ytd-icon-button-renderer yt-icon path, ytd-topbar-menu-button-renderer yt-icon path {
    color: #D3AF37 !important;
    fill: #D3AF37 !important;
  }
  ytd-thumbnail, ytd-thumbnail-overlay-time-status-renderer, ytd-thumbnail-overlay-bottom-panel-renderer, ytd-thumbnail-overlay-now-playing-renderer, ytd-thumbnail-overlay-resume-playback-renderer {
    background-color: #6f0000 !important;
    color: #D3AF37 !important;
  }
  :focus {
    outline: none !important;
    box-shadow: none !important;
  }
}
